const defaults={nav:'sidebar',wall:'forest',theme:'dark',accent:'#bbdf87',size:'1',animation:'normal',profile:'balanced',layout:'grid',clock:true};
let s;try{s={...defaults,...JSON.parse(localStorage.getItem('weberintv-settings')||'{}')}}catch{s={...defaults}}let page='home',category='Все',toastTimer;
const walls={forest:'radial-gradient(ellipse at 82% 38%,#5b7554 0%,#253f34 35%,#101c18 75%)',ocean:'radial-gradient(ellipse at 80% 30%,#537f88 0%,#24434b 40%,#101a20 80%)',sunset:'radial-gradient(ellipse at 80% 30%,#9d7156 0%,#513c3a 42%,#1b191d 80%)',night:'radial-gradient(ellipse at 80% 30%,#494b70 0%,#252a43 40%,#111520 80%)'};
const apps=[['YouTube','Видео','▶','#ff3b30'],['Кинопоиск','Кино','КИНОПОИСК','#ff7a00'],['Netflix','Кино','NETFLIX','#e50914'],['IVI','Кино','ivi','#e93668'],['Spotify','Музыка','● Spotify','#1ed760'],['Музыка','Музыка','♫','#bdabff'],['Галерея','Инструменты','▧','#ffc973'],['Настройки ТВ','Инструменты','⚙','#9ed3e0']];
const nav=[['home','⌂','Главная'],['apps','▦','Приложения'],['optimization','◈','Оптимизация'],['settings','⚙','Настройки']];
function save(){localStorage.setItem('weberintv-settings',JSON.stringify(s));render()}
function navButtons(){return nav.map(([id,icon,name])=>`<button class="navbtn ${page===id?'active':''}" data-page="${id}">${icon} <span class="label">${name}</span></button>`).join('')}
function tiles(list){return `<div class="tiles" style="${s.layout==='rows'?'grid-template-columns:repeat(auto-fill,minmax(220px,1fr))':''}">${list.map(a=>`<button class="tile" data-app="${a[0]}" style="--icon:${a[3]}"><span class="icon">${a[0]==='YouTube'?'<span class="youtube-play">▶</span> YouTube':a[2]}</span><span><strong>${a[0]}</strong><small>${a[1]}</small></span></button>`).join('')}</div>`}
function setting(label,desc,key,options){return `<div class="setting"><div><strong>${label}</strong><small>${desc}</small></div><select data-setting="${key}" aria-label="${label}">${options.map(([v,n])=>`<option value="${v}" ${String(s[key])===v?'selected':''}>${n}</option>`).join('')}</select></div>`}
function render(){let root=document.querySelector('#app');root.className=`${page==='home'?'explore-screen ':''}${s.nav==='top'?'top':s.nav==='minimal'?'minimal':''} theme-${s.theme}`;root.style.cssText=`--wall:${walls[s.wall]||walls.forest};--accent:${s.accent};--tile:${s.size};--speed:${s.animation==='off'?'0s':s.animation==='reduced'?'.08s':'.22s'}`;
let main='';if(page==='home')main=`<div class="explore"><div class="explore-hero"><div class="explore-shade"></div><div class="explore-copy"><div class="explore-label">ВЫБОР WEBERINTV &nbsp; / &nbsp; ВИДЕО</div><h1>Мир начинается<br>за горизонтом</h1><p class="explore-meta">Путешествия &nbsp; · &nbsp; 24 мин &nbsp; · &nbsp; Пример видео</p><p class="explore-description">Откройте для себя истории, места и идеи, которые хочется смотреть на большом экране.</p><div class="explore-buttons"><button class="explore-play" data-video="Мир начинается за горизонтом">▶ &nbsp; Смотреть</button><button class="explore-more" data-page="apps">▦ &nbsp; Приложения</button></div></div><div class="explore-mark">ДЕМОНСТРАЦИЯ</div></div><section class="video-section"><div class="video-header"><div><div class="video-eyebrow">СМОТРИТЕ НА БОЛЬШОМ ЭКРАНЕ</div><h2>Видео для вас</h2></div><span>Подборка-пример · YouTube не подключён</span></div><div class="video-rail">${[['Путешествие к краю земли','Путешествия','land'],['Как устроен современный мир','Наука и технологии','tech'],['Тихое утро в горах','Природа','mountain'],['Звуки большого города','Музыка','city'],['Всё о космосе','Наука','space']].map(v=>`<button class="video-card ${v[2]}" data-video="${v[0]}"><span class="video-art"><span class="video-play">▶</span><span class="video-duration">12:48</span></span><strong>${v[0]}</strong><small>${v[1]} · Пример</small></button>`).join('')}</div></section><section class="apps-section"><div class="video-header"><h2>Ваши приложения</h2><button class="all-apps" data-page="apps">Все приложения →</button></div>${tiles(apps.slice(0,6))}</section></div>`;
if(page==='apps')main=`<div class="panel"><h1>Приложения</h1><p>Всё нужное — рядом.</p><div class="topnav">${['Все','Кино','Видео','Музыка','Инструменты'].map(c=>`<button class="navbtn ${category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><br>${tiles(apps.filter(a=>category==='Все'||a[1]===category))}</div>`;
if(page==='settings')main=`<div class="panel"><h1>Настройки</h1><p>Сделайте WeberinTV своим. Изменения сохраняются в этом браузере.</p><div class="settings-grid">${setting('Навигация','Расположение меню','nav',[['sidebar','Слева'],['top','Сверху'],['minimal','Компактная']])}${setting('Расположение','Представление приложений','layout',[['grid','Сетка'],['rows','Широкие плитки']])}${setting('Обои','Цветовая атмосфера','wall',[['forest','Лес'],['ocean','Океан'],['sunset','Закат'],['night','Ночь']])}${setting('Тема','Оформление интерфейса','theme',[['dark','Тёмная'],['light','Светлая']])}<div class="setting"><div><strong>Акцентный цвет</strong><small>Цвет фокуса и кнопок</small></div><input type="color" data-setting="accent" value="${s.accent}" aria-label="Акцентный цвет"></div>${setting('Размер плиток','Плотность сетки','size',[['0.85','Маленькие'],['1','Средние'],['1.2','Большие']])}${setting('Анимация','Движение интерфейса','animation',[['normal','Обычная'],['reduced','Короткая'],['off','Выключена']])}${setting('Производительность','Набор визуальных настроек','profile',[['performance','Быстродействие'],['balanced','Баланс'],['visual','Визуальный']])}${setting('Часы','Время и дата на экране','clock',[['true','Показывать'],['false','Скрыть']])}<div class="setting"><div><strong>Сброс настроек</strong><small>Вернуть исходное оформление</small></div><button data-reset>Сбросить</button></div></div></div>`;
if(page==='optimization')main=`<div class="panel"><h1>Оптимизация системы</h1><p>Инструменты для осознанного управления телевизором.</p><div class="notice"><strong>Демонстрация в браузере</strong><br>Действия здесь ничего не меняют на телевизоре. Настоящие системные операции потребуют отдельного инструмента, проверки устройства и вашего согласия.</div>${[['◉','Состояние устройства','В реальном приложении здесь появится информация об устройстве.'],['◇','Проверка приложений','Потенциальные изменения будут показаны до выполнения.'],['↺','Восстановление','План возврата зависит от модели и выполненных операций.']].map(x=>`<div class="status"><button data-demo="${x[1]}">Подробнее</button><strong>${x[0]} &nbsp; ${x[1]}</strong><p class="muted">${x[2]}</p></div>`).join('')}</div>`;
root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Weberin<span>TV</span></div>${navButtons()}</aside><main class="content"><div class="topbar"><span class="eyebrow">${page==='home'?'ДОМА':'WEBERINTV'}</span><span class="clock">${s.clock===true||s.clock==='true'?new Intl.DateTimeFormat('ru-RU',{weekday:'long',hour:'2-digit',minute:'2-digit'}).format(new Date()):''}</span></div>${s.nav==='top'?`<nav class="topnav">${navButtons()}</nav>`:''}${main}</main></div>`;
}
function message(t){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=t;document.body.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),3000)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render()}else if(b.dataset.category){category=b.dataset.category;render()}else if(b.dataset.app)message(`«${b.dataset.app}» — демонстрационная плитка`);else if(b.dataset.video)message('Пример видео: YouTube пока не подключён');else if(b.dataset.demo)message('Демонстрация: системные изменения не выполняются');else if(b.hasAttribute('data-reset')){s={...defaults};save();message('Настройки сброшены')}});
document.addEventListener('change',e=>{let k=e.target.dataset.setting;if(!k)return;s[k]=e.target.value;if(k==='profile'){s.animation=s[k]==='performance'?'off':s[k]==='balanced'?'reduced':'normal'}save()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'||e.key==='Backspace'){if(document.activeElement.tagName==='SELECT')return;page='home';render();document.querySelector('.explore-play')?.focus();e.preventDefault();return}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)||['SELECT','INPUT'].includes(document.activeElement.tagName))return;let els=[...document.querySelectorAll('button,select,input')].filter(x=>x.offsetParent!==null),a=document.activeElement,rect=a.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2;let candidates=els.filter(x=>x!==a).map(x=>{let r=x.getBoundingClientRect(),dx=r.left+r.width/2-cx,dy=r.top+r.height/2-cy;let primary=e.key==='ArrowRight'?dx:e.key==='ArrowLeft'?-dx:e.key==='ArrowDown'?dy:-dy;let secondary=e.key==='ArrowRight'||e.key==='ArrowLeft'?Math.abs(dy):Math.abs(dx);return {x,primary,score:primary+secondary*2}}).filter(x=>x.primary>5).sort((a,b)=>a.score-b.score);if(candidates.length){candidates[0].x.focus();e.preventDefault()}});render();

document.addEventListener('focusin',e=>{const tile=e.target.closest('.clean-home .tile');const caption=document.querySelector('.clean-caption');if(tile&&caption)caption.textContent=tile.dataset.app});
